INSERT INTO exercises (name, muscle_group, type, description) VALUES
('Wyciskanie sztangi na ławce poziomej', 'CHEST', 'STRENGTH', 'W leżeniu na ławce opuszczaj sztangę w kierunku klatki piersiowej i wyciskaj ją do góry. Sprzęt: ławka i sztanga.'),
('Rozpiętki z hantlami na ławce', 'CHEST', 'STRENGTH', 'W leżeniu na ławce rozkładaj ramiona z hantlami na boki i zbliżaj je nad klatką piersiową, zachowując lekkie ugięcie łokci. Sprzęt: ławka i hantle.'),
('Pompki klasyczne', 'CHEST', 'HOME', 'W podporze na dłoniach i stopach opuszczaj tułów przez ugięcie łokci, następnie wracaj do pozycji wyjściowej. Bez dodatkowego sprzętu.'),
('Pompki przy ścianie', 'CHEST', 'HOME', 'Oprzyj dłonie o ścianę, uginaj łokcie, zbliżając do niej tułów, i odpychaj się do pozycji wyjściowej. Sprzęt: ściana.'),

('Wiosłowanie sztangą w opadzie', 'BACK', 'STRENGTH', 'W opadzie tułowia przyciągaj sztangę w kierunku brzucha i opuszczaj ją do wyprostu ramion. Sprzęt: sztanga.'),
('Ściąganie drążka wyciągu górnego', 'BACK', 'STRENGTH', 'Siedząc przy wyciągu, przyciągaj drążek przed sobą w kierunku górnej części klatki piersiowej i wracaj do wyprostu ramion. Sprzęt: wyciąg górny.'),
('Wiosłowanie gumą w siadzie', 'BACK', 'HOME', 'W siadzie z gumą opartą o stopy przyciągaj jej końce do tułowia i prostuj ramiona. Sprzęt: długa guma oporowa.'),
('Podciąganie nachwytem na drążku', 'BACK', 'HOME', 'Ze zwisu nachwytem podciągaj tułów w kierunku drążka i opuszczaj się do pozycji wyjściowej. Sprzęt: zamontowany drążek do podciągania.'),

('Wyciskanie hantli nad głowę', 'SHOULDERS', 'STRENGTH', 'Trzymając hantle przy barkach, wyciskaj je nad głowę i opuszczaj do pozycji wyjściowej. Sprzęt: hantle.'),
('Unoszenie hantli bokiem', 'SHOULDERS', 'STRENGTH', 'W staniu unoś ramiona z hantlami na boki do wysokości barków i opuszczaj je wzdłuż tułowia. Sprzęt: hantle.'),
('Pompki w pozycji pike', 'SHOULDERS', 'HOME', 'Z podporu z biodrami uniesionymi wysoko uginaj łokcie, kierując głowę w stronę podłoża, i prostuj ramiona. Bez dodatkowego sprzętu.'),
('Unoszenie ramion bokiem z butelkami', 'SHOULDERS', 'HOME', 'W staniu unoś ramiona z butelkami na boki do wysokości barków i opuszczaj je wzdłuż tułowia. Sprzęt: dwie zamknięte butelki z wodą.'),

('Uginanie ramion ze sztangą', 'BICEPS', 'STRENGTH', 'Trzymając sztangę podchwytem, uginaj łokcie, zbliżając ciężar do barków, i opuszczaj go. Sprzęt: sztanga.'),
('Uginanie ramion z hantlami chwytem młotkowym', 'BICEPS', 'STRENGTH', 'Uginaj łokcie z hantlami, utrzymując dłonie zwrócone do siebie, i wracaj do wyprostu ramion. Sprzęt: hantle.'),
('Uginanie ramion z gumą', 'BICEPS', 'HOME', 'Stań na środku gumy, chwyć jej końce i uginaj oraz prostuj łokcie. Sprzęt: długa guma oporowa.'),
('Uginanie ramion z butelkami', 'BICEPS', 'HOME', 'Trzymając butelki w dłoniach, uginaj łokcie, zbliżając dłonie do barków, i opuszczaj je. Sprzęt: dwie zamknięte butelki z wodą.'),

('Prostowanie ramion na wyciągu górnym', 'TRICEPS', 'STRENGTH', 'Stojąc przy wyciągu, prostuj łokcie, kierując uchwyt w dół, i wracaj do ich ugięcia. Sprzęt: wyciąg górny z uchwytem.'),
('Wyciskanie francuskie hantla oburącz', 'TRICEPS', 'STRENGTH', 'Trzymając hantel oburącz nad głową, uginaj łokcie, opuszczając go za głowę, i prostuj ramiona. Sprzęt: hantel.'),
('Pompki z wąskim ustawieniem dłoni', 'TRICEPS', 'HOME', 'Wykonuj pompkę z dłońmi ustawionymi węziej niż w wariancie klasycznym, uginając i prostując łokcie. Bez dodatkowego sprzętu.'),
